class ResourceGuard { // Implementation notes: The constructor acquires the resource, and the destructor releases it. The compiler ensures the destructor is called automatically on scope exit or exception. 
public: 
    ResourceGuard() { /* Acquire resource, e.g., allocate memory or open a file */ } 
    ~ResourceGuard() { /* Release resource, e.g., deallocate memory or close a file */ } 
    // Disable copying if necessary to prevent double release: 
    ResourceGuard(const ResourceGuard&) = delete; 
    ResourceGuard& operator=(const ResourceGuard&) = delete; 
}; 
// Usage: void function() { ResourceGuard guard; /* Resource is acquired here and released on function exit */ }
